const raw = $input.first().json;
const input = (raw && raw.body && typeof raw.body === 'object' && Object.keys(raw.body).length > 0) ? raw.body : raw;

const eventType = input.event_type || (input.delay_minutes ? 'route.delay_detected' : 'route.stop_en_route');
const delay = Number(input.delay_minutes || 0);
const isDelaySignificant = delay >= 15;

let isNotificationEligible = false;
let templateCode = 'vet_route_eta_notification';
let alertSummary = '';

switch (eventType) {
  case 'route.delay_detected':
    isNotificationEligible = isDelaySignificant;
    templateCode = 'vet_route_delay_notice';
    alertSummary = 'Retraso estimado de ' + delay + ' min para cita con ' + (input.client_name || 'cliente') + ' (' + (input.delay_reason || 'Tráfico Bogotá') + ').';
    break;
  case 'route.stop_en_route':
    isNotificationEligible = true;
    templateCode = 'vet_route_eta_notification';
    alertSummary = 'El ' + (input.vet_name || 'veterinario') + ' va en camino hacia el domicilio de ' + (input.pet_name || 'la mascota') + '. ETA: ' + (input.estimated_arrival || 'en camino') + '.';
    break;
  case 'route.stop_arrived':
    isNotificationEligible = true;
    templateCode = 'vet_route_arrived_notice';
    alertSummary = 'El ' + (input.vet_name || 'veterinario') + ' ha llegado al domicilio para la atención de ' + (input.pet_name || 'la mascota') + '.';
    break;
  case 'route.published':
    isNotificationEligible = false;
    alertSummary = 'Ruta ' + (input.route_code || input.route_id || '') + ' publicada con éxito para fecha ' + (input.route_date || 'hoy') + '.';
    break;
  case 'route.service_started':
  case 'route.service_completed':
    isNotificationEligible = false;
    alertSummary = 'Hito ' + eventType + ' registrado para parada ' + (input.stop_number || input.stop_id || '') + '.';
    break;
  default:
    isNotificationEligible = isDelaySignificant;
    alertSummary = 'Evento ' + eventType + ' procesado.';
}

return {
  json: {
    event_type: eventType,
    route_id: input.route_id,
    route_code: input.route_code,
    stop_id: input.stop_id,
    stop_number: input.stop_number || 1,
    vet_name: input.vet_name || 'Dr. Luis Ríos',
    client_name: input.client_name || 'Cliente Vet Life',
    client_phone: input.client_phone || '+573114445566',
    pet_name: input.pet_name || 'Mascota',
    estimated_arrival: input.estimated_arrival,
    delay_minutes: delay,
    delay_reason: input.delay_reason || 'Tráfico y condiciones operativas',
    is_delay_alert: isDelaySignificant,
    is_notification_eligible: isNotificationEligible,
    template_code: templateCode,
    alert_summary: alertSummary,
    send_enabled: false,
    processed_at: new Date().toISOString()
  }
};
